const assert=require('node:assert/strict');
const fs=require('node:fs');
const {Game,ITEMS}=require('./dist/engine.js');
const D=globalThis.GameData;
let passed=0;
function test(name,fn){fn();passed++;console.log('PASS '+name);}
function stepAndConfirm(g,...args){const r=g.publicStep(...args);if(r.ok)g.acknowledgePublicFeedback();return r;}
const fresh=(seed='test',opts={})=>Game.create(seed,opts);
test('catalog: 52 families / 260 unique vehicle forms / 124 items',()=>{assert.equal(D.vehicles.families.length,52);assert.equal(D.vehicles.vehicles.length,260);assert.equal(new Set(D.vehicles.vehicles.map(v=>v.id)).size,260);assert.equal(D.items.length,124);});
test('99 NPCs have unique names, valid voices, same-seed reproducibility',()=>{const a=fresh(),b=fresh();assert.equal(a.s.actors.length,100);assert.equal(new Set(a.s.actors.slice(1).map(x=>x.name)).size,99);assert.equal(a.serialize(),b.serialize());});
test('pause prevents elapsed simulation',()=>{const g=fresh();g.tick(10);assert.equal(g.s.minute,0);g.start();g.tick(.1);g.pause();const t=g.s.minute;g.tick(.1);assert.equal(g.s.minute,t);});
test('60 running seconds equal one day, excluding decision pauses',()=>{const g=fresh();g.hourly=()=>{};g.npcStep=()=>{};g.player.daily=60;g.work('rest','clock fixture',1440);for(let i=0;i<600;i++)g.tick(.1);assert.ok(Math.abs(g.s.minute-1440)<.00001);assert.equal(g.day,2);assert.equal(g.s.status,'playing');assert.equal(g.s.running,false);});
test('low frame rates keep the same time ratio',()=>{const g=fresh();g.hourly=()=>{};g.npcStep=()=>{};g.player.daily=60;g.work('rest','clock fixture',1440);for(let i=0;i<60;i++)g.tick(1);assert.equal(g.s.minute,1440);assert.equal(g.day,2);});
test('arrival stops precisely at node, then decisions freeze time',()=>{const g=fresh('arrival',{family:'F24',test:true});const target=g.s.route[0].km;g.advance(100,{moving:true});assert.equal(g.player.km,target);assert.equal(g.s.prompt.kind,'road');const t=g.s.minute;g.tick(.1);assert.equal(g.s.minute,t);});
test('fuel depletion rounds residue to zero and safely stops driving',()=>{const g=fresh('fuel',{family:'F24',test:true});g.player.energy=.00000001;g.consume(g.player,1,true);assert.equal(g.player.energy,0);g.start();g.tick(.1);assert.equal(g.s.running,false);assert.equal(g.s.status,'playing');});
test('fractional time boundaries cannot stall',()=>{const g=fresh('fractional');g.s.minute=59.99999999;g.s.lastHour=0;g.advance(.00001);assert.ok(g.s.minute>=60);assert.equal(g.s.lastHour,1);});
test('insufficient daily distance kills exactly at deadline',()=>{const g=fresh();g.s.minute=1439;g.s.lastNpc=47;g.s.lastHour=23;g.player.daily=59.999;g.advance(1);assert.equal(g.s.status,'dead');assert.match(g.player.reason,/里程|公里/);});
test('exact required distance passes, and next day resets only daily distance',()=>{const g=fresh();g.s.minute=1439;g.s.lastNpc=47;g.s.lastHour=23;g.player.daily=60;g.player.km=60;g.advance(1);assert.equal(g.s.status,'playing');assert.equal(g.day,2);assert.equal(g.player.daily,0);assert.equal(g.player.km,60);});
test('victory requires completion of day 30, not start of day 30',()=>{const g=fresh();g.hourly=()=>{};g.npcStep=()=>{};g.s.minute=29*1440;g.player.daily=180;g.player.hp=100;assert.equal(g.s.status,'playing');g.s.minute=30*1440-1;g.s.lastHour=Math.floor(g.s.minute/60);g.s.lastNpc=Math.floor(g.s.minute/30);g.advance(1);assert.equal(g.s.status,'won');assert.equal(g.s.minute,43200);});
test('30 daily settlements can reach victory without early win',()=>{const g=fresh();for(let d=1;d<=30;d++){assert.equal(g.s.status,'playing');g.player.daily=g.quota;g.s.minute=d*1440;g.endDay();g.s.prompt=null;}assert.equal(g.s.status,'won');});
test('limited inventory rejects overflow atomically, materials bypass slots',()=>{const g=fresh(),p=g.player;p.inv={};const cap=g.capacity();assert(g.add(p,'tool0',cap));const before=JSON.stringify(p.inv);assert.equal(g.add(p,'tool1'),false);assert.equal(JSON.stringify(p.inv),before);assert(g.add(p,'mat_metal',500));assert.equal(g.used(),cap);});
test('buy transfers owned stock and conserves currency, double buy blocked',()=>{const g=fresh(),l=g.s.listings[0],seller=g.s.actors.find(a=>a.id===l.seller);g.player.credits=999;const total=seller.credits+g.player.credits,old=g.player.inv[l.item]||0;assert(g.buy(l.id).ok);assert.equal(seller.credits+g.player.credits,total);assert.equal(g.player.inv[l.item],old+l.q);assert.equal(g.buy(l.id).ok,false);});
test('player listing reserves item and cancel restores exactly once',()=>{const g=fresh();const old=g.player.inv.food0;assert(g.sell('food0',4).ok);assert.equal(g.player.inv.food0,old-1);const l=g.s.listings.find(l=>l.seller==='P');assert(g.cancelListing(l.id).ok);assert.equal(g.player.inv.food0,old);assert.equal(g.cancelListing(l.id).ok,false);});
test('expired escrow returns items, capacity failure has explicit pending returns',()=>{const g=fresh();g.s.listings=[];const old=g.player.inv.food0;g.sell('food0',4);g.s.listings[0].expires=0;g.refreshMarket();assert.equal(g.player.inv.food0,old);});
test('dead NPCs lose listings and cannot speak or act',()=>{const g=fresh(),a=g.s.actors[1];g.kill(a,'fixture');const km=a.km,n=g.s.messages.length;g.say(a,'thanks');g.npcStep(30);assert.equal(a.km,km);assert.equal(g.s.messages.length,n);assert(!g.s.listings.some(l=>l.seller===a.id));});
test('NPCs advance on the same simulation clock',()=>{const g=fresh();const a=g.s.actors[1];g.advance(30);assert(g.s.lastNpc===1);assert(a.daily>0||a.action!=='整理物資');assert.equal(g.s.minute,30);});
test('aid transfers a real item and changes relationship',()=>{const g=fresh(),a=g.s.actors[1];const before=g.player.inv.water0,other=a.inv.water0||0;assert(g.help(a.id).ok);assert.equal(g.player.inv.water0,before-1);assert.equal(a.inv.water0,other+1);assert(gameTrust(g,a)>30);function gameTrust(g,a){return g.relation(a,'P').trust;}});
test('private trade uses real surplus, preserves reserve and transfers currency',()=>{const g=fresh(),a=g.s.actors[1];a.inv.gas=5;g.player.credits=100;const o=g.privateOffers(a.id).find(x=>x.item==='gas');assert(o);const total=a.credits+g.player.credits;assert(g.buyPrivate(a.id,'gas').ok);assert.equal(a.inv.gas,4);assert.equal(g.player.inv.gas,1);assert.equal(a.credits+g.player.credits,total);a.inv.gas=1;assert.equal(g.buyPrivate(a.id,'gas').ok,false);});
test('building shelter improves exposure and is lost when driving',()=>{const g=fresh('shelter',{family:'F01',test:true});g.s.weather={name:'high',type:'heat',s:55};g.player.shelter=35;const before=g.player.exposure;g.consume(g.player,30,false);const sheltered=g.player.exposure-before;g.player.exposure=0;g.consume(g.player,30,true);assert.equal(g.player.shelter,0);assert(g.player.exposure>sheltered);});
test('NPC-to-NPC aid consumes donor inventory',()=>{const g=fresh(),a=g.s.actors[1],b=g.s.actors[2];for(const n of g.s.actors.slice(3))n.alive=false;a.personality='互助';b.personality='互助';a.group=b.group=0;a.inv={water0:5};b.inv={food0:5};a.food=5;b.water=5;const before=a.inv.water0;g.socialStep();assert((a.inv.water0||0)<before);assert((b.inv.water0||0)>0);});
test('vehicle upgrade preserves family identity and pays real materials',()=>{const g=fresh('upgrade',{family:'F01',test:true});const family=g.player.family,old=g.player.mats.metal;assert(g.upgrade().ok);const work=g.s.work;g.finishWork(work);assert.equal(g.player.family,family);assert.equal(g.player.tier,2);assert(g.player.mats.metal<old);assert.equal(g.player.energy,0);});
test('all 52 families have valid starting capacity and usable stats',()=>{for(const f of D.vehicles.families){const g=fresh('family-'+f.id,{family:f.id,test:true});assert(g.used()<=g.capacity());assert(g.speed()>0);assert.equal(g.player.family,f.id);}});
test('restore retains random state, identities, inventory and current work',()=>{const g=fresh();g.work('rest','休息',100);g.advance(20);const restored=Game.restore(g.serialize());assert.equal(restored.s.rng,g.s.rng);assert.deepEqual(restored.s.actors,g.s.actors);assert.deepEqual(restored.s.work,g.s.work);assert.equal(restored.s.running,false);assert.equal(restored.random(),g.random());});
test('rest interruption does not clear pending work',()=>{const g=fresh();g.work('rest','休息',360);g.s.prompt={kind:'combat',enemy:'fixture',hp:30,attack:5};g.pause();assert.equal(g.s.work.left,360);g.skip();assert(g.s.work);});
test('18 forced test systems are distinct and safely execute',()=>{for(let id=0;id<18;id++){const g=fresh('sys-'+id,{test:true,system:id});g.player.mats.metal=50;g.player.mats.cloth=20;g.add(g.player,'tool0');assert.equal(g.s.system.id,id);const r=g.systemAction();assert.equal(typeof r.ok,'boolean');assert.equal(g.player.family,g.spec().familyId);}});
test('system is not forced by an unmarked normal-game option',()=>{const g=fresh('normal-not-forced',{system:17});assert(!g.s.test);assert.deepEqual(g.s.system,fresh('normal-not-forced').s.system);});
test('item catalog and UI have no missing referenced item IDs',()=>{for(const r of D.recipes)if(r.effect==='item')assert(ITEMS[r.value]);const html=fs.readFileSync('dist/index.html','utf8');assert(html.includes('roadCanvas'));assert(html.includes('30'));});
test('search results wait for selection, including materials, and freeze travel',()=>{const g=fresh('select');const before=JSON.stringify([g.player.inv,g.player.mats]);g.loot({name:'材料點',type:'materials',quality:.8});assert.equal(JSON.stringify([g.player.inv,g.player.mats]),before);assert(g.s.ground.length);g.start();assert.equal(g.s.running,false);const x={...g.s.ground[0]},old=g.player.mats[ITEMS[x.id].material]||0;assert(g.takeLoot(x.id,1).ok);assert.equal(g.player.mats[ITEMS[x.id].material],old+1);assert.equal(g.s.ground.find(y=>y.id===x.id)?.q||0,x.q-1);assert.equal(g.takeLoot(x.id,999).ok,false);const restored=Game.restore(g.serialize());assert.deepEqual(restored.s.ground,g.s.ground);assert.deepEqual(restored.s.loot,g.s.loot);g.leaveLoot();assert.equal(g.s.loot,null);assert.deepEqual(g.s.ground,[]);});
test('loot quantities are atomic and full bag can still take materials',()=>{const g=fresh(),p=g.player;p.inv={tool0:g.capacity()};g.s.loot={title:'fixture',taken:[]};g.s.ground=[{id:'food0',q:3},{id:'mat_metal',q:4}];const inv=JSON.stringify(p.inv);assert.equal(g.takeLoot('food0',1).ok,false);assert.equal(JSON.stringify(p.inv),inv);assert.equal(g.s.ground[0].q,3);assert(g.takeLoot('mat_metal',4).ok);assert.equal(g.takeLoot('food0',0).ok,false);assert.equal(g.takeLoot('food0',1.5).ok,false);assert(g.remove(p,'tool0'));assert(g.takeLoot('food0',1).ok);assert.equal(p.inv.food0,1);assert.equal(g.s.ground[0].q,2);});
test('equipment replaces one body slot and only worn protection applies',()=>{const g=fresh('wear',{family:'F01'}),p=g.player;p.inv={gear0:1,gear1:1,gear11:1};g.s.weather={type:'rain',s:80};const exposure=()=>{p.exposure=0;g.consume(p,30,false);return p.exposure;};const bare=exposure();assert(g.equip('gear0').ok);const protectedValue=exposure();assert(protectedValue<bare);assert(g.equip('gear1').ok);assert.deepEqual(p.equipment,{body:'gear1'});assert.equal(exposure(),bare);assert.equal(g.remove(p,'gear1'),false);assert.equal(g.sell('gear1',5).ok,false);assert(g.unequip('body').ok);assert(g.remove(p,'gear1'));assert.equal(g.equip('food0').ok,false);});
test('equipped weapon alone determines attack and ammo consumption',()=>{const g=fresh(),p=g.player;p.inv={weapon0:1,weapon8:1,ammo0:3,ammo1:3};const base=8+p.skill;assert.equal(g.attackPower(),base);g.equip('weapon0');assert.equal(g.attackPower(),base+5);g.s.prompt={kind:'combat',enemy:'fixture',hp:999,attack:0};g.fight();assert.equal(p.inv.ammo0,3);g.equip('weapon8');assert.equal(g.attackPower(),base+50);g.fight();assert.equal(p.inv.ammo0,3);assert.equal(p.inv.ammo1,2);assert.equal(g.used(),4);});
test('equipment survives saving and legacy saves start with empty equipment',()=>{const g=fresh();g.add(g.player,'gear0');g.equip('gear0');assert.deepEqual(Game.restore(g.serialize()).player.equipment,{body:'gear0'});const old=JSON.parse(g.serialize());for(const a of old.actors)delete a.equipment;old.ground=[];assert.deepEqual(Game.restore(JSON.stringify(old)).player.equipment,{});});
test('workshop status uses actual discounted costs and predicts payment',()=>{const g=fresh('discount',{test:true,system:8}),r=D.recipes.find(r=>['repair','tire','item','mat'].includes(r.effect)&&Object.values(r.cost).some(n=>n>=5));for(const k of Object.keys(g.player.mats))g.player.mats[k]=0;let status=g.craftStatus(r.id);assert.equal(status.ok,false);assert(g.materialStatus(status.cost).some(x=>x.missing));for(const [k,n]of Object.entries(status.cost))g.player.mats[k]=n;status=g.craftStatus(r.id);assert(status.ok);const before={...g.player.mats};assert(g.craft(r.id).ok);for(const [k,n]of Object.entries(status.cost)){assert.equal(g.player.mats[k],before[k]-n);assert.equal(n,Math.max(1,Math.ceil(r.cost[k]*.8)));}assert.equal(g.craftStatus(r.id).ok,false);});
test('upgrade status exposes shortage, date and condition requirements',()=>{const g=fresh('requirements',{family:'F01'}),p=g.player;p.mats={};let st=g.upgradeStatus();assert.equal(st.ok,false);assert(g.materialStatus(st.cost).some(x=>x.missing));for(const [k,n]of Object.entries(st.cost))p.mats[k]=n;p.condition=49;assert.match(g.upgradeStatus().text,/車況/);p.condition=80;assert(g.upgradeStatus().ok);g.upgrade();g.finishWork(g.s.work);g.s.work=null;assert.equal(p.tier,2);assert.equal(g.upgradeStatus().unlock,4);assert.match(g.upgradeStatus().text,/第 4 天/);});
test('legacy pending loot does not regrant items already received',()=>{const g=fresh();g.s.loot={title:'old loot',items:[{id:'food0',q:2}]};g.s.ground=[{id:'water0',q:1}];const old=g.player.inv.food0,restored=Game.restore(g.serialize());assert.equal(restored.player.inv.food0,old);assert.equal(restored.takeLoot('food0',2).ok,false);assert(restored.takeLoot('water0').ok);assert.equal(restored.player.inv.food0,old);});
test('expired goods cannot be bought and full inventory retains reclaimable stock',()=>{const g=fresh();g.s.listings=[];g.sell('food0',5);const l=g.s.listings[0];g.player.inv={tool0:g.capacity()};g.s.minute=l.expires;assert.equal(g.buy(l.id).ok,false);assert(!g.s.listings.some(x=>x.id===l.id));assert.deepEqual(g.player.returns,[{id:'food0',q:1}]);assert.equal(g.sell('tool0',5).ok,false);g.claimReturns(0);assert.equal(g.player.returns.length,1);g.remove(g.player,'tool0');g.claimReturns(0);assert.equal(g.player.inv.food0,1);assert.equal(g.player.returns.length,0);assert.equal(g.claimReturns(0).ok,false);});
test('manual delisting succeeds with full bag and puts goods in returns',()=>{const g=fresh();g.s.listings=[];g.sell('food0',5);const id=g.s.listings[0].id;g.player.inv={tool0:g.capacity()};assert(g.cancelListing(id).ok);assert.equal(g.s.listings.length,0);assert.deepEqual(g.player.returns,[{id:'food0',q:1}]);assert.equal(g.cancelListing(id).ok,false);g.expireListings();assert.equal(g.player.returns.length,1);});
test('claiming one return leaves other returns intact',()=>{const g=fresh();g.player.returns=[{id:'food0',q:1},{id:'water0',q:1}];const water=g.player.inv.water0;g.claimReturns(1);assert.equal(g.player.inv.water0,water+1);assert.deepEqual(g.player.returns,[{id:'food0',q:1}]);});
test('road spacing is wider while weak vehicles retain closer opportunities',()=>{for(const [family,min,max]of [['F01',14,24],['F24',26,44]]){const g=fresh('spacing',{family});let last=0;for(const n of g.s.route){assert(n.km-last>=min);assert(n.km-last<=max);last=n.km;}g.s.route=[];g.s.minute=7*1440;g.generateRoute();assert(g.s.route[0].km>=(family==='F01'?18:32));}});
test('legacy route migration preserves identity and runs only once',()=>{const g=fresh('old-spacing',{family:'F24'}),state=JSON.parse(g.serialize());delete state.balanceVersion;state.route.forEach((n,i)=>n.km=(i+1)*10);const restored=Game.restore(JSON.stringify(state));assert.equal(restored.s.balanceVersion,2);assert.equal(restored.s.route[0].name,state.route[0].name);assert(restored.s.route[0].km>=26);assert(restored.s.route[1].km-restored.s.route[0].km>=26);assert.deepEqual(restored.player.inv,g.player.inv);assert.deepEqual(Game.restore(restored.serialize()).s.route,restored.s.route);});
test('road hazards cost time or vehicle condition and produce no loot',()=>{for(const careful of [true,false]){const g=fresh('hazard'),p=g.player;g.s.prompt={kind:'road',node:{type:'flood',name:'積水路段'}};const before={stamina:p.stamina,tire:p.tire,condition:p.condition};assert.equal(g.search().ok,false);assert(g.crossHazard(careful).ok);if(careful){assert.equal(p.stamina,before.stamina-8);assert.equal(p.tire,before.tire);assert.equal(g.s.work.total,60);}else{assert.equal(p.tire,before.tire-8);assert.equal(p.condition,before.condition-4);assert.equal(g.s.work.total,10);}g.tick(3);assert.equal(g.s.loot,null);assert.equal(g.s.work,null);}});
test('hazards cannot be bypassed for free and failed careful crossing preserves prompt',()=>{const g=fresh();g.s.prompt={kind:'road',node:{type:'tree',name:'倒伏樹木'}};g.player.stamina=0;assert.equal(g.crossHazard(true).ok,false);assert(g.s.prompt);g.player.stamina=20;g.skip();assert.equal(g.s.prompt,null);assert.equal(g.s.work.type,'hazard');});
test('radio provides forecast after paid work and never produces loot',()=>{const g=fresh();g.s.prompt={kind:'road',node:{type:'radio',name:'異常廣播'}};assert(g.inspectSignal().ok);assert.equal(g.s.work.total,15);g.tick(1);assert(g.s.forecast);assert.equal(g.s.loot,null);});
test('quick searches stay small and deep rare caches have bounded variety',()=>{for(let i=0;i<60;i++)for(const deep of [true,false]){const g=fresh('bounded-'+i);g.s.system=null;g.loot({name:'cache',type:'mixed',quality:.95},deep);const extra=x=>ITEMS[x.id].kind==='module'||['icecream','iceblock','warmer'].includes(x.id);assert(g.s.loot.items.filter(x=>!extra(x)).length<=(deep?4:2));assert(g.s.ground.length<=(deep?6:4));}});
test('deep searches take longer and night injuries are greater',()=>{for(const night of [false,true]){const g=fresh('risk');g.s.minute=night?720:0;g.roll=()=>true;g.s.prompt={kind:'road',node:{type:'materials',name:'warehouse',quality:0}};assert(g.search(true).ok);assert.equal(g.s.work.total,150);const hp=g.player.hp;g.loot(g.s.work.node,true);assert.equal(g.player.hp,hp-(night?13:8));}});
test('reduced routine consumption compensates for longer supply intervals',()=>{const g=fresh(),p=g.player;g.s.weather={type:'none',s:0};g.consume(p,60,false);assert.equal(p.food,83);assert.equal(p.water,82);g.s.weather={type:'heat',s:0};g.consume(p,60,false);assert.equal(p.food,81);assert.equal(p.water,77);});
test('material batch sale reserves exactly five wood for a total of fifteen credits',()=>{const g=fresh(),p=g.player;p.mats.wood=8;const money=p.credits;assert(g.sell('mat_wood',15,5).ok);const l=g.s.listings.find(x=>x.seller==='P');assert.equal(l.q,5);assert.equal(l.price,15);assert.equal(p.mats.wood,3);assert.equal(p.credits,money);assert(g.cancelListing(l.id).ok);assert.equal(p.mats.wood,8);assert.equal(g.cancelListing(l.id).ok,false);});
test('buying a material batch transfers total price and all units even with full bag',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];a.mats.wood=20;p.inv={tool0:g.capacity()};p.credits=100;const before=p.mats.wood||0,total=p.credits+a.credits;assert(g.postListing(a,'mat_wood',5,15).ok);const l=g.s.listings.find(x=>x.seller===a.id&&x.item==='mat_wood');assert(g.buy(l.id).ok);assert.equal(p.mats.wood,before+5);assert.equal(a.mats.wood,15);assert.equal(a.credits+p.credits,total);assert.equal(g.used(),g.capacity());});
test('expired material batches return once without needing bag space',()=>{const g=fresh(),p=g.player;p.mats.wood=8;g.sell('mat_wood',15,5);const l=g.s.listings.find(x=>x.seller==='P');p.inv={tool0:g.capacity()};g.s.minute=l.expires;g.expireListings();g.expireListings();assert.equal(p.mats.wood,8);assert(!p.returns?.length);});
test('player demand reserves budget and NPC fulfillment conserves stock and currency',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];g.s.requests=[];a.mats.wood=20;p.mats.wood=0;const total=p.credits+a.credits;assert(g.postRequest('mat_wood',5,15).ok);assert.equal(p.credits,15);const r=g.s.requests[0];assert.equal(r.price,15);assert(g.fulfillRequest(r.id,a).ok);assert.equal(p.mats.wood,5);assert.equal(a.mats.wood,15);assert.equal(p.credits+a.credits,total);assert.equal(g.fulfillRequest(r.id,a).ok,false);});
test('player can fulfill an NPC demand at its quoted batch total',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];g.s.requests=[];p.mats.wood=8;a.credits=50;const money=p.credits;assert(g.postRequest('mat_wood',5,15,a).ok);assert.equal(a.credits,35);const before=a.mats.wood||0;assert(g.fulfillRequest(g.s.requests[0].id).ok);assert.equal(p.mats.wood,3);assert.equal(a.mats.wood,before+5);assert.equal(p.credits,money+15);});
test('cancelled and expired demands refund their budgets exactly once',()=>{const g=fresh(),p=g.player;g.s.requests=[];const money=p.credits;g.postRequest('food0',1,5);const id=g.s.requests[0].id;assert(g.cancelRequest(id).ok);assert.equal(p.credits,money);assert.equal(g.cancelRequest(id).ok,false);g.postRequest('water0',1,5);g.s.minute=g.s.requests[0].expires;g.expireRequests();g.expireRequests();assert.equal(p.credits,money);assert.equal(g.s.requests.length,0);});
test('demand buyer capacity failure is atomic and can be retried after freeing space',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];g.s.requests=[];p.inv={tool0:g.capacity()};a.inv.food0=8;g.postRequest('food0',2,8);const id=g.s.requests[0].id,stock=a.inv.food0,money=a.credits;assert.equal(g.fulfillRequest(id,a).ok,false);assert.equal(a.inv.food0,stock);assert.equal(a.credits,money);assert.equal(g.s.requests.length,1);g.remove(p,'tool0');assert(g.fulfillRequest(id,a).ok);assert.equal(p.inv.food0,2);});
test('invalid batch quantities and prices do not debit stock or money',()=>{const g=fresh(),p=g.player;p.mats.wood=10;const state=g.serialize();for(const q of [0,-1,1.5,10000,NaN]){assert.equal(g.sell('mat_wood',15,q).ok,false);assert.equal(g.postRequest('mat_wood',q,15).ok,false);}for(const price of [0,-1,1.5,100000,NaN]){assert.equal(g.sell('mat_wood',price,5).ok,false);assert.equal(g.postRequest('mat_wood',5,price).ok,false);}assert.equal(g.serialize(),state);});
test('death refunds NPC demand escrow and removes its outstanding demands',()=>{const g=fresh(),a=g.s.actors[1];g.s.requests=[];a.credits=50;g.postRequest('mat_wood',5,15,a);g.kill(a,'test');assert.equal(a.credits,50);assert(!g.s.requests.some(r=>r.buyer===a.id));});
test('gifting selected quantities moves real stock and rejects worn or overflowing gifts',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];const own=p.inv.water0,other=a.inv.water0;assert(g.help(a.id,'water0',2).ok);assert.equal(p.inv.water0,own-2);assert.equal(a.inv.water0,other+2);p.mats.wood=8;const wood=a.mats.wood||0;assert(g.help(a.id,'mat_wood',5).ok);assert.equal(p.mats.wood,3);assert.equal(a.mats.wood,wood+5);g.add(p,'gear0');g.equip('gear0');const before=a.inv.gear0||0;assert.equal(g.help(a.id,'gear0',1).ok,false);assert.equal(a.inv.gear0||0,before);a.inv={tool0:g.capacity(a)};assert.equal(g.help(a.id,'water0',1).ok,false);assert.equal(p.inv.water0,own-2);});
test('specific aid request never substitutes food for water and enforces cooldown at minute zero',()=>{const g=fresh(),a=g.s.actors[1],p=g.player;a.personality='互助';a.inv={food0:8,water0:1};g.roll=()=>true;const food=p.inv.food0;assert(g.ask(a.id,'water').ok);assert.equal(p.inv.food0,food);assert.equal(g.ask(a.id,'food').ok,false);g.s.minute=120;a.inv.water0=4;const water=p.inv.water0;assert(g.ask(a.id,'water').ok);assert.equal(p.inv.water0,water+1);assert.equal(a.inv.water0,3);});
test('NPC demand matching only supplies surplus NPC stock without taking player goods',()=>{const g=fresh(),p=g.player,a=g.s.actors[1];g.s.requests=[];a.mats.wood=20;p.mats.wood=0;g.postRequest('mat_wood',5,15);g.pick=xs=>xs[0];g.matchRequests();assert.equal(p.mats.wood,5);assert.equal(a.mats.wood,15);assert.equal(g.s.requests.length,0);});
test('NPCs post multi-unit material sale listings and demand budgets survive saving',()=>{const g=fresh(),a=g.s.actors[1];g.s.listings=[];g.s.requests=[];a.mats.wood=20;for(const n of g.s.actors.slice(2))n.alive=false;g.pick=xs=>xs.find(x=>x.id==='mat_wood')||xs[0];g.refreshMarket();assert(g.s.listings.some(l=>l.seller===a.id&&l.item==='mat_wood'&&l.q===5));const before=g.serialize(),r=Game.restore(before);assert.deepEqual(r.s.requests,g.s.requests);assert.deepEqual(r.s.listings,g.s.listings);});
test('scouting includes exactly three km and hides distant and passed targets',()=>{const g=fresh();g.player.km=10;g.s.route=[{name:'passed',km:9},{name:'here',km:10},{name:'edge',km:13},{name:'hidden',km:13.000001}];assert.deepEqual(g.visibleRoute().map(n=>n.name),['here','edge']);g.player.km=10.000001;assert(g.visibleRoute().some(n=>n.name==='hidden'));assert(!g.visibleRoute().some(n=>n.name==='here'));assert.deepEqual(Game.restore(g.serialize()).visibleRoute(),g.visibleRoute());});
test('personal scouting respects its own 20 and 10 km limits without changing ordinary scouting',()=>{for(const [id,range] of [[1,20],[3,10]]){const g=fresh('scan',{test:true,system:id});g.s.route=[{name:'SECRET_TARGET',desc:'SECRET_REWARD',km:g.player.km+range+.001}];let r=g.systemAction();assert(!r.text.includes('SECRET'));assert(r.text.includes(range+' 公里'));g.s.system.used=0;g.s.route[0].km=g.player.km+range;r=g.systemAction();assert(r.text.includes('SECRET_TARGET'));assert.equal(g.visibleRoute().length,0);}});

function shopper(personality='冒險'){const g=fresh('shop'),a=g.s.actors[1];g.s.listings=[];g.s.requests=[];a.inv={};a.credits=200;a.food=85;a.water=85;a.personality=personality;return {g,a,p:g.player};}
test('NPC compares batch unit prices instead of lowest batch total',()=>{const {g,a,p}=shopper();p.mats.wood=20;a.mats.wood=0;g.sell('mat_wood',6,2);g.sell('mat_wood',10,5);const total=p.credits+a.credits;const l=g.npcPurchase(a);assert.equal(l.q,5);assert.equal(l.price,10);assert.equal(a.mats.wood,5);assert.equal(p.credits+a.credits,total);});
test('equivalent food effects compare price while different effects remain distinct',()=>{const {g,a,p}=shopper();a.food=20;p.inv={food0:2,food17:2};g.sell('food0',6);g.sell('food17',5);assert.equal(g.tradeClass('food0'),g.tradeClass('food17'));assert.equal(g.npcPurchase(a).item,'food17');});
test('NPC consumes own food and water to 60 before judging purchase',()=>{const {g,a,p}=shopper();a.food=0;a.water=19;a.inv={food0:2,water0:2};p.inv={food0:5,water0:5};g.sell('food0',4);g.sell('water0',4);assert.equal(g.npcPurchase(a),null);assert.equal(a.food,64);assert.equal(a.water,99);assert.deepEqual(a.inv,{});assert.equal(a.credits,200);});
test('NPC can buy after consuming insufficient stored food',()=>{const {g,a,p}=shopper();a.food=0;a.inv={food0:1};p.inv={food0:5};g.sell('food0',4);assert(g.npcPurchase(a));assert.equal(a.food,32);assert.equal(a.inv.food0,1);});
test('NPC rejects weaker and equal gear, weapons and tools, accepts upgrades',()=>{const {g,a}=shopper();a.inv={weapon3:1,tool4:1,gear10:1};g.s.weather={type:'rain',s:60};assert.equal(g.npcNeed(a,'weapon0'),0);assert.equal(g.npcNeed(a,'weapon3'),0);assert(g.npcNeed(a,'weapon8')>0);assert.equal(g.npcNeed(a,'tool0'),0);assert.equal(g.npcNeed(a,'tool9'),0);assert.equal(g.npcNeed(a,'gear11'),0);assert(g.npcNeed(a,'gear0')>0);g.add(a,'gear0');assert(g.equipped(a).includes('gear0'));assert(!g.equipped(a).includes('gear10'));});
test('medicine buying follows damage and specific treatment conditions',()=>{const {g,a}=shopper();for(const id of ['med0','med2','med4','med5','med8','med9'])assert.equal(g.npcNeed(a,id),0);a.hp=80;assert(g.npcNeed(a,'med1')>0);a.hp=100;a.bleed=2;assert(g.npcNeed(a,'med0')>0);assert.equal(g.npcNeed(a,'med3'),0);a.infection=1;assert(g.npcNeed(a,'med3')>0);a.pain=1;assert(g.npcNeed(a,'med4')>0);a.san=40;assert(g.npcNeed(a,'med5')>0);a.stamina=20;assert(g.npcNeed(a,'med9')>0);a.inv.med1=1;assert.equal(g.npcNeed(a,'med0'),0);});
test('medicines clear corresponding infection, pain and fatigue conditions',()=>{const {g,a}=shopper();a.inv={med2:1,med4:1,med9:1};a.infection=1;a.pain=1;a.stamina=20;g.useItem(a,'med2');g.useItem(a,'med4');g.useItem(a,'med9');assert.equal(a.infection,0);assert.equal(a.pain,0);assert.equal(a.stamina,45);});
test('NPC buys only ammo matching equipped weapon and only when empty',()=>{const {g,a}=shopper();for(const [weapon,ammo]of [['weapon5','ammo2'],['weapon6','ammo0'],['weapon7','ammo3'],['weapon8','ammo1']]){a.inv={[weapon]:1};for(const id of ['ammo0','ammo1','ammo2','ammo3'])assert.equal(g.npcNeed(a,id)>0,id===ammo);a.inv[ammo]=1;assert.equal(g.npcNeed(a,ammo),0);}a.inv={weapon0:1};assert.equal(g.npcNeed(a,'ammo0'),0);});
test('personality changes price tolerance, priorities and cash reserve',()=>{const {g,a,p}=shopper('商人');a.mats.wood=0;p.mats.wood=10;g.sell('mat_wood',13,5);assert.equal(g.npcPurchase(a),null);a.personality='技師';assert(g.npcPurchase(a));assert(g.npcPolicy(a,ITEMS.tool0).priority>g.npcPolicy(a,ITEMS.food0).priority);const b=shopper('謹慎');b.p.mats.wood=5;b.a.mats.wood=0;b.a.credits=15;b.g.sell('mat_wood',10,5);assert.equal(b.g.npcPurchase(b.a),null);b.a.personality='冒險';assert(b.g.npcPurchase(b.a));});
test('purchase selection excludes expired, own and overflowing batches without debit',()=>{const {g,a,p}=shopper();a.inv={tool0:g.capacity(a)};a.food=20;p.inv={food0:5};g.sell('food0',4);const cash=a.credits;assert.equal(g.npcPurchase(a),null);assert.equal(a.credits,cash);a.inv={};g.s.minute=1440;assert.equal(g.npcPurchase(a),null);});
test('all three sign-in levels grant 2,4,8 units and are atomic when bag is full',()=>{for(const [L,q,xp,day]of [[1,2,0,1],[2,4,200,4],[3,8,600,10]]){const g=fresh('sign',{test:true,system:0});g.s.minute=(day-1)*1440;g.s.system.xp=xp;g.player.inv={};assert.equal(g.level(),L);assert(g.systemAction().ok);assert.equal(g.player.inv.food0,q);assert.equal(g.player.inv.water0,q);assert.equal(g.systemAction().ok,false);}const g=fresh('atomic',{test:true,system:0});g.player.inv={tool0:g.capacity()-1};const before=g.serialize();assert.equal(g.systemAction().ok,false);assert.equal(g.serialize(),before);});
test('system XP thresholds double, only first benefit earns daily XP including across saves',()=>{const g=fresh('xp',{test:true,system:1});assert(g.systemAction().ok);assert.equal(g.s.system.xp,30);g.systemAction();g.systemXp();assert.equal(g.s.system.xp,30);const restored=Game.restore(g.serialize());restored.systemXp();assert.equal(restored.s.system.xp,30);g.s.dayStats={};g.systemXp();assert.equal(g.s.system.xp,60);g.s.minute=9*1440;for(const [xp,L]of [[199,1],[200,2],[599,2],[600,3]]){g.s.system.xp=xp;assert.equal(g.level(),L);}});
test('daily intelligence has exactly one forecast at every level and reduces weather harm',()=>{for(const [L,xp,day]of [[1,0,1],[2,200,4],[3,600,10]]){const g=fresh('weather',{test:true,system:2}),base=fresh('weather');g.s.minute=(day-1)*1440;g.s.system.xp=xp;assert(g.systemAction().ok);assert.equal(g.systemAction().ok,false);for(const x of [g,base]){x.player.exposure=100;x.player.hp=100;x.player.san=100;x.s.weather={type:'acid',s:100};}g.consume(g.player,60,false);base.consume(base.player,60,false);assert(Math.abs((100-g.player.hp)-(100-base.player.hp)*(1-L*.1))<1e-8);assert(Math.abs((100-g.player.san)-(100-base.player.san)*(1-L*.1))<1e-8);}});
test('contract protects one public instance and obeys 1/2/3 daily charges',()=>{for(const [L,xp,day]of [[1,0,1],[2,200,4],[3,600,10]]){const g=fresh('contract',{test:true,system:13}),p=g.player;g.s.minute=(day-1)*1440;g.s.system.xp=xp;for(const actor of g.s.actors.slice(1)){actor.greed=90;actor.personality='強硬';actor.rels={P:{like:0,trust:0,debt:0}};}g.roll=()=>true;for(let i=0;i<L;i++){assert(g.systemAction().ok);assert.equal(g.systemAction().ok,false);g.s.prompt=null;assert(g.beginPublic('repair'));assert(g.s.publicInstance.contract);assert(!p.mods.contract);g.s.publicInstance.goal=999;stepAndConfirm(g,'guard');assert(!g.s.publicInstance.log.some(x=>x.includes('趁亂')||x.includes('奪走')));g.finishPublic(true,'contract test');g.acknowledgePublic();}assert.equal(g.systemAction().ok,false);}});

test('real purchase and next NPC action buy then apply needed medication',()=>{const {g,a,p}=shopper();a.hp=70;a.bleed=1;p.inv={med1:1};g.sell('med1',15);const before=p.credits+a.credits;assert.equal(g.npcPurchase(a).item,'med1');assert.equal(p.credits+a.credits,before);g.npcStep(0);assert.equal(a.bleed,0);assert.equal(a.hp,100);assert(!a.inv.med1);});
test('actual ammo purchase rejects mismatched ammo and buys matching ammo once',()=>{const {g,a,p}=shopper();a.inv={weapon7:1};p.inv={ammo0:3,ammo3:3};g.sell('ammo0',1);g.sell('ammo3',14);assert.equal(g.npcPurchase(a).item,'ammo3');assert.equal(g.npcPurchase(a),null);assert.equal(a.inv.ammo3,1);assert(!a.inv.ammo0);});
test('personality ranks needed gear classes without overriding same-quality price preference',()=>{const {g,a,p}=shopper('強硬');p.inv={weapon0:2,tool0:2};g.sell('weapon0',5);g.sell('tool0',8);assert.equal(g.npcPurchase(a).item,'weapon0');const b=shopper('技師');b.p.inv={weapon0:2,tool0:2};b.g.sell('weapon0',5);b.g.sell('tool0',8);assert.equal(b.g.npcPurchase(b.a).item,'tool0');});
test('passive system XP only credits actual benefit once, viewing and settlement do not grant it',()=>{const g=fresh('passive',{test:true,system:10});g.systemAction();assert.equal(g.s.system.xp,0);g.consume(g.player,5,true);assert.equal(g.s.system.xp,30);g.consume(g.player,5,true);assert.equal(g.s.system.xp,30);const h=fresh('settle',{test:true,system:1});h.s.minute=1440;for(const a of h.s.actors)a.daily=60;h.endDay();assert.equal(h.s.system.xp,0);});
test('thirty daily XP reaches level two on day seven and level three on day twenty',()=>{const g=fresh('daily-30',{test:true,system:1});for(let day=1;day<=30;day++){g.s.minute=(day-1)*1440;g.s.dayStats={};g.systemXp();g.systemXp();assert.equal(g.s.system.xp,day*30);assert.equal(g.level(),day<7?1:day<20?2:3);}});

test('ambient catalog has 168 distinct personality and situation lines',()=>{const lines=require('./dist/dialogue.js'),all=[];assert.equal(Object.keys(lines).length,7);for(const topics of Object.values(lines)){assert.equal(Object.keys(topics).length,8);for(const values of Object.values(topics)){assert.equal(values.length,3);all.push(...values);}}assert.equal(all.length,168);assert.equal(new Set(all).size,168);});
test('new arrivals express uncertainty with distinct opening speech',()=>{const g=fresh('opening'),messages=g.s.messages.filter(m=>m.topic==='arrival');assert(messages.length>=6);assert.equal(new Set(messages.map(m=>m.text)).size,messages.length);assert(messages.every(m=>m.time===0));assert.equal(g.serialize(),fresh('opening').serialize());});
test('ambient topic follows real hunger thirst weather night and attack context',()=>{const g=fresh('topics'),a=g.s.actors[1];g.s.minute=300;assert.equal(g.ambientTopic(a),'idle');a.food=20;assert.equal(g.ambientTopic(a),'hunger');a.water=20;assert.equal(g.ambientTopic(a),'thirst');assert.equal(g.ambient(a,'attack'),false);a.lastAttack=300;assert.equal(g.ambientTopic(a),'attack');g.s.minute=391;a.food=a.water=80;g.s.weather={name:'酸雨',type:'acid',s:80};assert.equal(g.ambientTopic(a),'weather');g.s.minute=720;assert.equal(g.ambientTopic(a),'night');g.s.minute=1440;g.s.weather={name:'晴朗',type:'none',s:0};assert.equal(g.ambientTopic(a),'dawn');});
test('night resting NPC stays silent except actual danger or critical shortage',()=>{const g=fresh('sleep'),a=g.s.actors[1];g.s.minute=720;a.action='休息';const before=g.s.messages.length;assert.equal(g.ambient(a,'night'),false);assert.equal(g.say(a,'status',{fact:'休息'}),false);assert.equal(g.s.messages.length,before);a.lastAttack=720;assert(g.ambient(a,'attack'));assert.equal(g.s.messages[0].topic,'attack');const b=g.s.actors[2];b.action='休息';b.water=10;g.s.minute=780;assert(g.ambient(b,'thirst'));});
test('night urgent speech is globally throttled to at most one per game hour',()=>{const g=fresh('urgent-night');g.s.minute=720;g.s.chatState={last:-99999,recent:[],speakers:[]};for(const a of g.s.actors.slice(1,6)){a.lastAttack=720;a.lastAmbient=-99999;a.chatTopics={};}assert(g.ambient(g.s.actors[1],'attack'));assert.equal(g.ambient(g.s.actors[2],'attack'),false);g.s.minute=779;assert.equal(g.ambient(g.s.actors[2],'attack'),false);g.s.minute=780;assert(g.ambient(g.s.actors[2],'attack'));});
test('ambient repetition memory and cooldowns persist after restoring',()=>{const g=fresh('remember'),a=g.s.actors[1];g.s.minute=300;a.personality='謹慎';assert(g.ambient(a,'idle'));const first=g.s.messages[0].text;let restored=Game.restore(g.serialize()),other=restored.s.actors[1];assert.equal(restored.ambient(other,'idle'),false);restored.s.minute=660;assert(restored.ambient(other,'idle'));assert.notEqual(restored.s.messages[0].text,first);assert(restored.s.chatState.recent.includes(first));other.alive=false;restored.s.minute=1800;assert.equal(restored.ambient(other,'idle'),false);});
test('daytime chatter has higher attempt rate than night and pause creates no speech',()=>{const day=fresh('rate'),night=fresh('rate');for(const g of [day,night]){g.s.chatState={last:-99999,recent:[],speakers:[]};for(const a of g.s.actors.slice(1)){a.action='前進';a.lastAmbient=-99999;a.chatTopics={};}g.roll=p=>p>.5;}day.s.minute=300;night.s.minute=720;const d=day.s.messages.length,n=night.s.messages.length;day.ambientChatter();night.ambientChatter();assert.equal(day.s.messages.length,d+1);assert.equal(night.s.messages.length,n);const before=day.serialize();day.pause();day.tick(60);assert.equal(day.s.messages.length,d+1);});
test('standalone channel is directly reachable and not embedded in survivor list',()=>{const html=fs.readFileSync('dist/index.html','utf8'),app=fs.readFileSync('dist/app.js','utf8');assert(html.includes('data-pane="channel">☷'));assert(html.includes('data-pane="channel">打開區域頻道'));assert(html.includes('<script src="dialogue.js"></script>'));const society=app.slice(app.indexOf('function society()'),app.indexOf('function channel()'));assert(!society.includes('chat-line'));assert(app.includes("if(name==='channel')channel()"));});

test('night NPC-to-NPC fills stay silent while player-related deliveries remain visible',()=>{const g=fresh('nighttrade');g.s.minute=720;g.s.requests=[];const a=g.s.actors[1],b=g.s.actors[2];a.credits=100;b.mats.wood=20;g.postRequest('mat_wood',3,6,a);const before=g.s.messages.length;assert(g.fulfillRequest(g.s.requests[0].id,b).ok);assert.equal(g.s.messages.length,before);g.player.credits=100;g.postRequest('mat_wood',3,6);const n=g.s.messages.length;assert(g.fulfillRequest(g.s.requests[0].id,b).ok);assert.equal(g.s.messages.length,n+1);});
test('a new day releases used ambient lines without resetting cooldowns or repeating recent messages',()=>{const g=fresh('newchatday');const a=g.s.actors[1];g.s.minute=1440;for(const actor of g.s.actors)actor.daily=60;a.lastAmbient=1400;a.chatRecent=['old line'];g.s.chatState={last:1400,recent:['old line'],speakers:[a.id]};g.endDay();assert.deepEqual(a.chatRecent,[]);assert.deepEqual(g.s.chatState.recent,[]);assert.equal(a.lastAmbient,1400);assert.equal(g.s.chatState.last,1400);});

function combatFixture(){const g=fresh('feedback',{family:'F24',test:true});g.s.minute=720;g.s.lastHour=12;g.s.lastNpc=24;g.s.prompt={kind:'combat',enemy:'測試怪物',hp:1000,attack:12};g.player.armor=4;return g;}
test('combat feedback reports actual damage, ammo use and holds the next choice',()=>{const g=combatFixture();g.player.inv={weapon6:1,ammo0:2};g.equip('weapon6');const hp=g.player.hp;assert(g.combatAction('fight').ok);const f=g.s.combatFeedback;assert.equal(f.action,'fight');assert(f.damageDealt>0);assert(f.enemyHP>0);assert(f.ongoing);assert.equal(f.minutes,2);assert.equal(f.delta.hp,g.player.hp-hp);assert.equal(f.delta.armor,-4);assert(f.changes.some(x=>x.name===ITEMS.ammo0.name&&x.q===-1));const before=g.serialize();assert.equal(g.combatAction('fight').ok,false);g.start();g.tick(60);assert.equal(g.serialize(),before);});
test('combat victory reports granted loot and handles a full bag accurately',()=>{for(const full of [false,true]){const g=combatFixture();g.s.prompt.hp=1;if(full)g.player.inv={tool0:g.capacity()};assert(g.combatAction('fight').ok);const f=g.s.combatFeedback;assert(f.success);assert.equal(f.enemyHP,0);assert(!f.ongoing);assert(f.changes.some(x=>x.name==='金屬'&&x.q===3));assert.equal(f.changes.some(x=>x.name===ITEMS.food0.name&&x.q===1),!full);assert.equal(f.foodLost,full);assert(g.acknowledgeCombat());assert.equal(g.acknowledgeCombat(),false);assert.equal(g.s.running,false);}});
test('hide success and failure both return explicit feedback with real time and damage',()=>{for(const success of [true,false]){const g=combatFixture();g.roll=()=>success;g.combatAction('hide');const f=g.s.combatFeedback;assert.equal(f.success,success);assert.equal(f.ongoing,!success);assert.equal(f.minutes,success?20:0);assert.equal(f.damageDealt,0);assert.equal(f.delta.hp<0,!success);assert(f.text.length);}});
test('escape success reports distance and fuel spent while failure reports injury',()=>{for(const success of [true,false]){const g=combatFixture();g.roll=()=>success;g.combatAction('escape');const f=g.s.combatFeedback;assert.equal(f.success,success);assert.equal(f.ongoing,!success);assert.equal(f.km>0,success);assert.equal(f.delta.energy<0,success);assert.equal(f.delta.hp<0,!success);assert.equal(g.s.running,false);}});
test('escape without fuel still shows failure and counterattack feedback',()=>{const g=combatFixture();g.player.energy=0;g.combatAction('escape');const f=g.s.combatFeedback;assert(!f.success);assert(f.ongoing);assert.equal(f.minutes,0);assert(f.delta.hp<0);assert(f.text.includes('沒有能源'));});
test('lethal combat feedback survives saving before showing death screen',()=>{const g=combatFixture();g.player.hp=1;g.player.armor=0;g.combatAction('fight');assert.equal(g.s.status,'dead');assert(g.s.combatFeedback.dead);assert(g.s.combatFeedback.reason);const restored=Game.restore(g.serialize());assert.deepEqual(restored.s.combatFeedback,g.s.combatFeedback);assert(restored.acknowledgeCombat());assert.equal(restored.s.status,'dead');assert(!restored.s.combatFeedback);});
test('acknowledging feedback preserves interrupted rest and follow-up roadside event',()=>{const g=combatFixture();g.s.work={type:'rest',label:'休息',left:100,total:100};g.roll=()=>true;g.combatAction('hide');g.acknowledgeCombat();assert.equal(g.s.work.left,100);assert.equal(g.s.running,false);const h=combatFixture();h.s.route[0].km=h.player.km+.1;h.roll=()=>true;h.combatAction('escape');assert.equal(h.s.prompt.kind,'road');assert(h.s.combatFeedback);h.acknowledgeCombat();assert.equal(h.s.prompt.kind,'road');});
test('popup rendering takes priority over prompts and death with explicit acknowledgement',()=>{const app=fs.readFileSync('dist/app.js','utf8');assert(app.indexOf('if(s.combatFeedback)')<app.indexOf("if(s.status!=='playing')"));assert(app.includes("game.combatAction(a)"));assert(app.includes('data-action="combatFeedbackDone"'));assert(app.includes("'ACTION REPORT',false"));});

test('art covers 52 families at five stages with unique side and road illustrations',()=>{const art=require('./dist/art.js'),side=new Set(),top=new Set();assert.equal(art.configs.length,52);for(const f of D.vehicles.families)for(let tier=1;tier<=5;tier++){for(const [set,view]of [[side,false],[top,true]]){const svg=art.vehicle(f.id,tier,view);assert(svg.startsWith('<svg'));assert(svg.endsWith('</svg>'));assert(!/NaN|undefined|Infinity/.test(svg));set.add(svg);}}assert.equal(side.size,260);assert.equal(top.size,260);});
test('all 18 buildings and 12 road events have distinct valid vector scenes',()=>{const art=require('./dist/art.js'),all=new Set();for(const b of D.buildings){const svg=art.node({name:b[0],type:b[1],building:true});assert(!/NaN|undefined/.test(svg));all.add(svg);}for(const e of D.events){const svg=art.node({name:e[0],type:e[2],building:false});assert(!/NaN|undefined/.test(svg));all.add(svg);}assert.equal(all.size,30);});
test('art sources are offline and wired into driving, encounters, upgrades and standalone export',()=>{const app=fs.readFileSync('dist/app.js','utf8'),html=fs.readFileSync('dist/index.html','utf8'),build=fs.readFileSync('make_standalone.py','utf8'),art=require('./dist/art.js');assert(art.url(art.vehicle('F02',1)).startsWith('data:image/svg+xml'));assert(html.includes('id="vehiclePortrait"'));assert(html.includes('<script src="art.js"></script>'));assert(build.includes("'art.js'"));assert(app.includes("nodePicture(n,'encounter-art')"));assert(app.includes("vehiclePicture(p.family,i+1,n,'stage-art')"));assert(app.includes('artImage(vehicleSource(v.family,v.tier,true))'));assert(app.includes('game?.visibleRoute()'));assert(app.includes("case 'artCatalog'"));});

test('inventory splits five-unit stacks, repacks after use and exposes partial pickup capacity',()=>{const g=fresh('stacks');g.player.inv={water0:8};assert.deepEqual(g.inventorySlots().map(x=>x.q),[5,3]);g.player.water=40;const r=g.playerUse('water0');assert(r.ok);assert.deepEqual(r.changes.find(x=>x.label==='水分'),{label:'水分',before:40,after:80});assert.deepEqual(g.inventorySlots().map(x=>x.q),[5,2]);g.player.inv={tool0:g.capacity()-1,water0:2};assert.equal(g.lootCapacity('water0'),3);g.s.loot={title:'loot',taken:[],choiceVersion:1};g.s.ground=[{id:'water0',q:6}];assert(!g.takeLoot('water0',6).ok);assert(g.takeLoot('water0',3).ok);assert.equal(g.s.ground[0].q,3);assert.equal(g.used(),g.capacity());});
test('item use reports clamped actual recovery rather than nominal amount',()=>{const g=fresh();g.player.water=90;const r=g.playerUse('water0');assert.equal(r.changes.find(x=>x.label==='水分').after,100);g.player.water=100;const stock=g.player.inv.water0;assert(!g.playerUse('water0').ok);assert.equal(g.player.inv.water0,stock);});
test('weather starts normal for three days, has 12 disasters and deterministic graded schedules',()=>{const types=new Set(),grades=new Set();for(let n=0;n<30;n++){const g=fresh('climate-'+n);for(let d=1;d<=3;d++)assert.equal(g.weatherFor(d).type,'none');for(let d=4;d<=30;d++){const w=g.weatherFor(d);assert.deepEqual(w,g.weatherFor(d));if(w.type!=='none'){types.add(w.id);grades.add(w.grade);assert(w.startsAt>=(d-1)*1440);assert(w.endsAt<=d*1440);if(d<8)assert.equal(w.grade,1);if(d<15)assert(w.grade<=2);}}}assert.equal(types.size,12);assert.equal(grades.size,3);});
test('weather is inactive before forecast start and after its end',()=>{const g=fresh('window');let w;for(let d=4;d<=30;d++)if(g.weatherFor(d).type!=='none'){w=g.weatherFor(d);break;}g.s.minute=w.startsAt-1;g.updateWeather();assert.equal(g.s.weather.type,'none');g.s.minute=w.startsAt;g.updateWeather();assert.equal(g.s.weather.id,w.id);g.s.minute=w.endsAt;g.updateWeather();assert.equal(g.s.weather.type,'none');});
test('all 13 module categories have three beneficial levels and work on every family',()=>{assert.equal(D.expansion.modules.length,13);for(const f of D.vehicles.families){const g=fresh('universal',{family:f.id}),base=g.spec();g.add(g.player,'module_climate');assert(g.installModule('module_climate').ok);g.s.weather={type:'heat',s:90};assert(g.weatherProtection()>=base.weatherProtection+30);assert.equal(g.spec().energyPer100Km,base.energyPer100Km);g.add(g.player,'module_climate');assert(!g.installModule('module_climate').ok);assert.equal(g.player.modules.climate,1);}});
test('module upgrade pays exact materials and applies only after work completes',()=>{const g=fresh('module',{family:'F01'});g.add(g.player,'module_climate');g.installModule('module_climate');let st=g.moduleStatus('climate');for(const [k,n]of Object.entries(st.cost))g.player.mats[k]=n;assert(g.upgradeModule('climate').ok);assert.equal(g.player.modules.climate,1);g.finishWork(g.s.work);g.s.work=null;assert.equal(g.player.modules.climate,2);for(const k of Object.keys(st.cost))assert.equal(g.player.mats[k],0);assert(!g.upgradeModule('climate').ok);});
test('appropriate weather protection prevents new exposure and mechanical disaster damage',()=>{for(const [type,cat]of [['rain','seal'],['cold','climate'],['heat','climate'],['quake','stability'],['wind','stability'],['dust','air'],['acid','corrosion'],['hail','armor'],['thunder','electric'],['snow','terrain'],['ice','terrain'],['fog','sensor']]){const g=fresh('shield',{family:'F01'}),p=g.player;g.s.weather={type,s:80,grade:3};p.modules[cat]=3;const hp=p.hp,condition=p.condition;g.consume(p,30,false);assert.equal(p.exposure,0,type);assert.equal(p.hp,hp,type);assert.equal(p.condition,condition,type);}});
test('unprotected quake damages vehicle and body while buffs expire and ice melts',()=>{const g=fresh('damage',{family:'F01'});g.s.weather={type:'quake',s:90};g.consume(g.player,60,false);assert(g.player.condition<80);assert(g.player.hp<100);g.add(g.player,'iceblock');assert(g.playerUse('iceblock').ok);assert(g.player.weatherBuffs.length);assert(!g.playerUse('iceblock').ok);g.add(g.player,'icecream');g.s.minute=500;g.s.weather={type:'none',s:0};g.consume(g.player,1,false);assert(!g.player.inv.icecream);assert.equal(g.player.weatherBuffs.length,0);});
test('cargo energy and medicine modules benefit without imposing costs',()=>{const g=fresh('benefits',{family:'F24'}),p=g.player,capacity=g.capacity(),tank=g.spec().tankOrBatteryCapacity,rate=g.spec().energyPer100Km;p.modules.cargo=3;p.modules.energy=3;assert.equal(g.capacity(),capacity+20);assert.equal(g.spec().tankOrBatteryCapacity,tank*2);assert(g.spec().energyPer100Km<rate);p.modules.medical=3;p.hp=50;p.inv.med1=1;g.playerUse('med1');assert.equal(p.hp,98);});
test('public instance freezes road time including work NPCs weather and listing expiry',()=>{const g=fresh('instance');g.s.minute=3*1440;g.s.prompt=null;assert(g.beginPublic('find'));const minute=g.s.minute,npcKM=g.s.actors[1].km;g.start();g.tick(100);g.advance(100,{moving:true});assert.equal(g.s.minute,minute);assert.equal(g.s.actors[1].km,npcKM);assert(g.s.publicInstance.participants.length>=2&&g.s.publicInstance.participants.length<=5);assert(g.s.publicInstance.guide.id.startsWith('TEMP-'));assert.equal(g.s.actors.length,100);assert.equal(g.s.running,false);});
test('all twelve public types have distinct objectives and can settle without road time',()=>{assert.equal(D.expansion.publicTypes.length,12);for(const type of D.expansion.publicTypes){const g=fresh('public-'+type.id);g.s.minute=3*1440;g.s.prompt=null;assert(g.beginPublic(type.id));for(const id of g.s.publicInstance.participants){const a=g.publicActor(id);a.personality='互助';a.greed=0;a.mats.parts=50;a.mats.circuit=50;a.mats.metal=50;a.mats.wood=50;a.inv={weapon8:1,ammo1:30,med1:10};a.equipment={weapon:'weapon8'};a.hp=100;}g.roll=()=>true;const before=g.s.minute;for(let i=0;i<12&&g.s.publicInstance;i++)assert(stepAndConfirm(g,'objective').ok);assert(g.s.publicResult,type.id);assert(g.s.publicResult.success,type.id);assert.equal(g.s.minute,before);assert.equal(g.s.actors.length,100);assert(!g.s.publicInstance);}});
test('failed public event charges each survivor once and kills those unable to pay',()=>{const g=fresh('fail');g.s.prompt=null;g.beginPublic('puzzle');const ids=[...g.s.publicInstance.participants],fee=g.s.publicInstance.penalty;g.player.credits=fee-1;for(const id of ids.slice(1))g.publicActor(id).credits=fee;assert(g.finishPublic(false,'test'));assert.equal(g.s.status,'dead');assert(g.s.publicResult.results.find(x=>x.id==='P').dead);for(const id of ids.slice(1))assert.equal(g.publicActor(id).credits,0);const state=g.serialize();assert.equal(g.finishPublic(false,'again'),false);assert.equal(g.serialize(),state);});
test('public victory gives finite rewards and full-bag module goes to returns',()=>{const g=fresh('reward');g.s.prompt=null;g.beginPublic('hunt');g.player.inv={tool0:g.capacity()};const money=g.player.credits,award=g.s.publicInstance.reward;g.finishPublic(true,'complete');assert.equal(g.player.credits,money+award);assert(g.player.returns.some(x=>ITEMS[x.id].kind==='module'));assert(g.acknowledgePublic());assert(!g.acknowledgePublic());assert.equal(g.s.running,false);});
test('public aid attack and plunder affect real NPC state and matching ammo',()=>{const g=fresh('interaction');g.s.prompt=null;g.beginPublic('hunt');g.s.publicInstance.enemyHP=9999;g.s.publicInstance.goal=9999;const id=g.s.publicInstance.participants[1],a=g.publicActor(id);a.hp=30;g.player.inv={med1:3,weapon6:1,ammo0:3};g.player.equipment.weapon='weapon6';g.roll=()=>false;const before=a.hp;assert(stepAndConfirm(g,'aid',id).ok);assert(a.hp>before);assert.equal(g.player.inv.med1,2);const hp=a.hp;assert(stepAndConfirm(g,'attack',id).ok);assert(a.hp<hp);assert.equal(g.player.inv.ammo0,2);a.inv={water0:5};const own=g.player.inv.water0||0;assert(stepAndConfirm(g,'steal',id).ok);assert.equal(g.player.inv.water0,own+1);assert.equal(a.inv.water0,4);});
test('pending public state persists through save restore with temporary guide isolated',()=>{const g=fresh('persist-public');g.s.prompt=null;g.beginPublic('repair');const r=Game.restore(g.serialize());assert.deepEqual(r.s.publicInstance,g.s.publicInstance);assert(!r.s.actors.some(a=>a.id===r.s.publicInstance.guide.id));assert.equal(r.s.actors.length,100);});
test('automatic public trigger respects initial days and distance cooldown',()=>{const g=fresh('trigger');g.roll=()=>true;g.player.km=100;g.s.publicCooldown=30;assert(!g.tryPublicEvent());g.s.minute=3*1440;assert(g.tryPublicEvent());assert(!g.tryPublicEvent());g.finishPublic(true,'test');g.acknowledgePublic();assert(!g.tryPublicEvent());});
test('NPC consumes matching weather supply once and keeps surplus for later',()=>{const g=fresh('npc-weather');const a=g.s.actors[1];a.inv={warmer:2};a.modules={};a.equipment={};a.shelter=0;g.s.weather={type:'cold',s:200};g.npcStep(0);assert.equal(a.inv.warmer,1);assert(a.weatherBuffs.some(b=>b.id==='warmer'));g.npcStep(0);assert.equal(a.inv.warmer,1);});
test('legacy module migration preserves armor and runs only once',()=>{const g=fresh('legacy-mod');delete g.s.expansionVersion;g.player.mods={armor:120,slots:8};g.player.modules={};g.ensureExpansion();assert.equal(g.player.modules.armor,3);assert.equal(g.player.legacyArmor,20);assert.equal(g.player.modules.cargo,2);const spec=g.spec();g.ensureExpansion();assert.deepEqual(g.spec(),spec);});
test('rest module grants no healing while paused',()=>{const g=fresh('paused-bed');g.player.modules.bed=3;g.player.hp=50;g.work('rest','休息',60);g.pause();g.tick(10);assert.equal(g.player.hp,50);});
test('public round feedback captures actions and blocks a second turn until confirmed',()=>{const g=fresh('round-feedback');g.beginPublic('hunt');g.s.publicInstance.enemyHP=9999;g.s.publicInstance.goal=9999;g.player.inv={water0:2};g.player.water=40;assert(g.publicStep('item','water0').ok);const f=g.s.publicFeedback;assert.equal(f.round,1);assert(f.log.some(x=>x.includes('使用')));assert(f.actors[0].changes.some(x=>x.label==='水分'&&x.before===40&&x.after===80));assert(f.supplies.some(x=>x.q===-1));const snapshot=g.serialize();assert(!g.publicStep('guard').ok);assert.equal(g.serialize(),snapshot);assert(g.acknowledgePublicFeedback());assert(!g.acknowledgePublicFeedback());assert(g.publicStep('guard').ok);});
test('final round feedback persists before successful or failed settlement acknowledgement',()=>{for(const success of [true,false]){const g=fresh('final-feedback');g.beginPublic('hunt');g.s.publicInstance.enemyHP=success?1:9999;g.s.publicInstance.goal=1;g.s.publicInstance.limit=1;assert(g.publicStep('objective').ok);assert(g.s.publicFeedback.finished);assert.equal(g.s.publicResult.success,success);assert(!g.acknowledgePublic());const r=Game.restore(g.serialize());assert.deepEqual(r.s.publicFeedback,g.s.publicFeedback);const minute=r.s.minute;r.start();r.tick(1);assert.equal(r.s.minute,minute);assert(r.acknowledgePublicFeedback());assert(r.acknowledgePublic());}});
test('scaled public objectives require multiple rounds even when every participant succeeds',()=>{for(const type of D.expansion.publicTypes)for(const count of [2,5])for(const day of [4,15,30]){const g=fresh('quota-'+type.id+'-'+count+'-'+day);g.s.minute=(day-1)*1440;g.random=()=>count===2?0:.99;assert(g.beginPublic(type.id));const e=g.s.publicInstance;assert.equal(e.participants.length,count);if(!['combat','defend'].includes(type.mode))assert(e.goal>=count*4);for(const id of e.participants){const a=g.publicActor(id);a.personality='技師';a.greed=0;a.skill=8;a.armor=1000;a.inv={weapon8:1,ammo1:100,med1:30};a.equipment={weapon:'weapon8'};a.mats={metal:100,wood:100,parts:100,circuit:100,chemical:100};}g.roll=()=>true;let rounds=0;while(g.s.publicInstance&&rounds<30){assert(stepAndConfirm(g,'objective').ok);rounds++;if(rounds===1)assert(!g.s.publicResult,type.id+' completed in one turn');}assert(g.s.publicResult?.success,type.id+' count '+count+' day '+day);assert(rounds>=3,type.id+' too short');assert(rounds<=e.limit);}});
test('clearing one monster wave cannot advance into another wave during the same round',()=>{const g=fresh('wave-barrier');g.beginPublic('hunt');const e=g.s.publicInstance;e.enemyHP=1;g.player.inv={weapon8:1,ammo1:10};g.player.equipment={weapon:'weapon8'};assert(g.publicStep('objective').ok);assert.equal(e.progress,1);assert.equal(e.wave,2);assert.equal(e.enemyHP,e.enemyMax);assert(g.s.publicFeedback.log.some(x=>x.includes('下回合')));assert(!g.s.publicResult);});
